package workcmd

func managementCommands() []Command {
	command := func(name, summary string, fields []InputField) Command {
		return Command{Name: name, Version: 1, CredentialPurpose: "worker", Summary: summary, Scope: "current explicit run and real admitted human instruction; global edits need trusted management policy or team ownership", InputFields: fields, Result: "status, operation_id, object_id, revision, replay; new responsibilities apply to future execution snapshots."}
	}
	return []Command{
		command("private.project-context", "Read only the project/context explicitly fixed for this private run, subject to current human access.", nil),
		command("private.project-content", "Read an authorized project content pointer through the current private project view.", []InputField{{"content_id", "Content ID in the explicitly selected project; private/global alternatives are rejected."}}),
		command("private.context", "Read this private context and its explicit project view without borrowing project ownership.", nil),
		command("private.navigate", "Select an authorized personal/project view from the actual current human instruction.", []InputField{{"key", "Stable operation key."}, {"action", "Explicit navigation action."}, {"project_scope_id", "Optional authorized project scope."}, {"context_id", "Optional selected existing context."}, {"expected_revision", "Exact navigation revision."}, {"source_message_id", "Actual human input admitted to this run."}}),
		command("private.adopt-instruction", "Deliberately share only a human-requested minimal summary from private discussion into the selected project.", []InputField{{"key", "Stable adoption key."}, {"source_message_id", "Actual admitted human instruction authorizing the move."}, {"title", "Explicit project task title."}, {"summary", "Minimal deliberately disclosed project summary; private source bodies remain private."}}),
		command("role.list", "Discover configured role responsibilities; bootstrap may build a new team when no team exists.", []InputField{{"limit", "Default 20, maximum 100."}, {"after", "Previous next_cursor."}}),
		command("role.inspect", "Read role responsibilities and the current project's independent override.", []InputField{{"role_id", "Visible role ID."}}),
		command("role.update-description", "Save natural-language responsibilities without changing model profiles; project changes remain local.", []InputField{{"key", "Stable idempotency key."}, {"role_id", "Authorized target role."}, {"scope", "Explicit project or global; global requires a real private/management authorization."}, {"expected_revision", "Global role revision, or project override revision (zero creates)."}, {"description", "Human-requested natural-language responsibilities."}, {"source_message_id", "Actual human instruction admitted to this run."}}),
		command("team.list", "Discover teams visible to this bound role or principal.", []InputField{{"limit", "Default 20, maximum 100."}, {"after", "Previous next_cursor."}}),
		command("team.inspect", "Read one authorized team and its configured roster.", []InputField{{"team_id", "Visible team."}}),
		command("team.create", "Create a persistent team during bootstrap, owned by the actual initiating human.", []InputField{{"key", "Stable creation key."}, {"name", "Team name."}, {"leader_role_id", "Current bound bootstrap leader role."}, {"member_role_ids", "Explicit configured role choices."}, {"source_message_id", "Actual bootstrap human instruction admitted to this run."}}),
		command("team.update", "Update team name and default leader through owner or trusted management authorization.", []InputField{{"key", "Stable update key."}, {"team_id", "Managed team."}, {"expected_revision", "Exact team revision."}, {"name", "Desired team name."}, {"leader_role_id", "Active roster member; existing project leaders are independent."}, {"source_message_id", "Actual current human management instruction."}}),
		command("team.member.add", "Add a configured role to the persistent team roster.", []InputField{{"key", "Stable operation key."}, {"team_id", "Managed team."}, {"expected_revision", "Exact team revision."}, {"role_id", "Configured bound role."}, {"expected_member_revision", "Exact membership revision, or zero creates."}, {"source_message_id", "Actual current human instruction."}}),
		command("team.member.remove", "Remove a roster role after explicit removal from live projects; historical work stays preserved.", []InputField{{"key", "Stable operation key."}, {"team_id", "Managed team."}, {"expected_revision", "Exact team revision."}, {"role_id", "Existing nonleader roster role."}, {"expected_member_revision", "Exact membership revision."}, {"source_message_id", "Actual current human instruction."}}),
	}
}
